"""Template helpers for the v2 UI: lucide icons and status tones."""

from __future__ import annotations

import json
from functools import cache
from pathlib import Path

from django import template
from django.utils.html import format_html, json_script
from django.utils.safestring import mark_safe

register = template.Library()

_ICONS_PATH = Path(__file__).with_name("lucide_icons.json")


@cache
def _icons() -> dict[str, str]:
    # Generated by frontend/scripts/gen-icons.mjs (`npm run icons`).
    return json.loads(_ICONS_PATH.read_text(encoding="utf-8"))


@register.simple_tag
def icon(name: str, cls: str = "size-4", label: str = ""):
    """Inline lucide SVG. Decorative unless ``label`` is given."""
    body = _icons().get(name)
    if body is None:
        raise template.TemplateSyntaxError(f"unknown icon {name!r}; add it to gen-icons.mjs")
    a11y = (
        format_html('role="img" aria-label="{}"', label) if label else mark_safe('aria-hidden="true"')
    )
    return format_html(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" '
        'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" '
        'class="shrink-0 {}" {}>{}</svg>',
        cls,
        a11y,
        mark_safe(body),
    )


# One tone per status value across projects, jobs, objectives and findings.
_TONES = {
    "active": "success",
    "running": "info",
    "in_progress": "info",
    "pending": "neutral",
    "idle": "neutral",
    "paused": "warning",
    "blocked": "warning",
    "finished": "neutral",
    "completed": "success",
    "fixed": "success",
    "confirmed": "danger",
    "open": "warning",
    "finished_with_errors": "danger",
    "failed": "danger",
    "cancelled": "neutral",
    "false_positive": "neutral",
    "accepted": "neutral",
    # severities
    "critical": "danger",
    "high": "danger",
    "medium": "warning",
    "low": "info",
    "info": "neutral",
}


@register.filter
def status_tone(value) -> str:
    return _TONES.get(str(value or "").lower(), "neutral")


@register.simple_tag
def flash_payload(messages) -> list[dict[str, str]]:
    """Django messages as ``[{level, text}]`` for the toaster island's json_script."""
    return [{"level": m.tags or "info", "text": str(m)} for m in messages or []]


@register.simple_tag
def island(name: str, element_id: str = "", **props):
    """Mount point for a React island, with its props as escaped JSON.

    ``{% island "command-palette" searchUrl=search_url %}`` renders a
    ``json_script`` block plus ``<div data-island="…" data-props="…">``; the
    page entry (frontend/src/entries/*.ts) registers the matching component.
    """
    props_id = f"island-{element_id or name}-props"
    return format_html(
        '{}<div data-island="{}" data-props="{}"{}></div>',
        json_script(props, props_id),
        name,
        props_id,
        format_html(' id="{}"', element_id) if element_id else "",
    )
